            aOrbiterD = ((aWandererD + RotL64(aScatter, 13U)) + 0xA278D0D866D9AE4DULL) + aTwistOrbiterAssignSaltB[(((255U - aIndex) + 196U)) & S_SALT1];
            aOrbiterE = (aWandererJ + RotL64(aCross, 39U)) + 0x656356135275B793ULL;
