            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterG, 30U));
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterC, 13U));
            aIngress = aIngress + RotL64(aOrbiterH, 19U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererE = aWandererE ^ ((RotL64(aCross, 35U) + aOrbiterB) + RotL64(aOrbiterG, 29U));
            aWandererH = aWandererH + (((RotL64(aScatter, 13U) + aOrbiterB) + RotL64(aOrbiterD, 11U)) + RotL64(aCarry, 41U));
            aWandererC = aWandererC ^ ((RotL64(aIngress, 58U) + aOrbiterA) + RotL64(aOrbiterH, 18U));
            aWandererD = aWandererD + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterH, 35U)) + aOrbiterC) + RotL64(aCarry, 21U));
            aWandererF = aWandererF ^ ((RotL64(aCross, 19U) + aOrbiterE) + RotL64(aOrbiterD, 43U));
            aWandererJ = aWandererJ + ((RotL64(aScatter, 47U) + aOrbiterI) + RotL64(aOrbiterD, 39U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 29U) + RotL64(aOrbiterI, 3U)) + aOrbiterC);
            aWandererA = aWandererA + (((RotL64(aPrevious, 52U) + RotL64(aOrbiterK, 53U)) + aOrbiterC) + aTwistWandererUpdateSaltE[((aIndex + 221U)) & S_SALT1]);
            aWandererK = aWandererK ^ (((RotL64(aCross, 41U) + RotL64(aOrbiterK, 58U)) + aOrbiterG) + aTwistWandererUpdateSaltB[(((255U - aIndex) + 142U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererJ ^ RotL64(aWandererH, 43U));
