            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x656D672E0ADADE21ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 163U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xC8158AB6F4F77B83ULL;
