            aCross = (RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 13519U)) & S_BLOCK1], 37U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 8948U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aIceLaneD[((S_BLOCK1 - aIndex + 13736U)) & S_BLOCK1], 11U) ^ RotL64(aKeyRowReadA[(((2047U - aIndex) + 8862U)) & W_KEY1], 26U));
