            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x9D60FAE96432B191ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xCE59E9378EF323BDULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xDE522B3ABF81F3E2ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x86BD954B5D204F75ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x446AECFD93D4F8E9ULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0xD8F5A0538D9B85EDULL) + aKeyRotateAOrbiterUpdateSaltE[(((255U - aIndex) + 232U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x98D13D47EC7418C8ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF08F89FA97A5FD29ULL), 53U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x28AADB9691CD2BC9ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0xD731C05DF6D7049FULL;
            aOrbiterB = RotL64((aOrbiterB * 0x587A17A779F20773ULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xE17AAC5FB6472074ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0x88E2C43D90C99439ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 208U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x7ADDC455D0124E17ULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x7840DED36E1B8C04ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x43A529C888D57B6FULL;
