            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x19F4CEFB8FC0B09BULL) + aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xD7B24A6C74187501ULL;
