            aOrbiterI = (aWandererI + RotL64(aScatter, 41U)) + 0x479BE89B15F71C2DULL;
            aOrbiterH = ((aWandererF + RotL64(aIngress, 57U)) + RotL64(aCarry, 37U)) + 0xE4D2C73CE672989CULL;
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 53U)) + 0xAF705C54C4E46D9AULL) + aKeyRotateBOrbiterAssignSaltD[((aIndex + 107U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aCross, 35U)) + RotL64(aCarry, 11U)) + 0x4531B1C8C672AAABULL;
            aOrbiterK = (aWandererE + RotL64(aIngress, 20U)) + 0x32E8440F63C8E4DAULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x7D9DEE0F52A79B60ULL;
