            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x6CDF98A932DC69C0ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0x4D43A917B2ED348AULL) ^ aKeyRotateBOrbiterUpdateSaltC[((aIndex + 166U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x267499DBC7020C15ULL), 57U);
