            aWandererC = aWandererC ^ ((RotL64(aCross, 29U) + aOrbiterF) + RotL64(aOrbiterD, 5U));
            aWandererJ = aWandererJ + ((RotL64(aScatter, 24U) + RotL64(aOrbiterJ, 43U)) + aOrbiterG);
            aWandererH = aWandererH ^ (((RotL64(aIngress, 35U) + aOrbiterC) + RotL64(aOrbiterH, 11U)) + aKeyRotateBWandererUpdateSaltE[(((255U - aIndex) + 71U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererH, 39U) ^ aWandererC);
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererJ, 4U));
