            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x4784C91E37529CD3ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x95BD9410126A6503ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x4AC646610F47462BULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x482415B7CE2C31D8ULL) ^ aKeyRotateBOrbiterUpdateSaltC[((aIndex + 145U)) & S_SALT1];
