            aWandererF = aWandererF ^ (((RotL64(aPrevious, 38U) + aOrbiterJ) + RotL64(aOrbiterA, 43U)) + aKeyRotateBWandererUpdateSaltE[(((255U - aIndex) + 194U)) & S_SALT1]);
            aWandererE = aWandererE + ((RotL64(aIngress, 41U) + RotL64(aOrbiterE, 39U)) + aOrbiterC);
