            //
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 13U)) + RotL64(aCarry, 5U)) + 0x71505B4996F519D1ULL;
            aOrbiterC = (aWandererC + RotL64(aCross, 3U)) + 0x302E1EBCEBC64BCFULL;
            aOrbiterJ = ((aWandererA + RotL64(aIngress, 35U)) + 0x1B67D82296889F08ULL) + aKeyRotateBOrbiterAssignSaltD[(((255U - aIndex) + 138U)) & S_SALT1];
            aOrbiterD = ((aWandererI + RotL64(aScatter, 27U)) + RotL64(aCarry, 57U)) + 0x9D31EB21CAF73663ULL;
            aOrbiterH = ((aWandererB + RotL64(aIngress, 43U)) + RotL64(aCarry, 27U)) + 0x093C18C2F40DED57ULL;
