            aOrbiterK = (aWandererG + RotL64(aPrevious, 19U)) + 0xD99A77D5218E0A23ULL;
            aOrbiterB = (aWandererE + RotL64(aCross, 39U)) + 0x445851D420711A7BULL;
            aOrbiterI = (aWandererJ + RotL64(aScatter, 29U)) + 0xF752ACCEB696F8F1ULL;
            aOrbiterG = (aWandererD + RotL64(aCross, 10U)) + 0x747BF29F944ADEEBULL;
            aOrbiterF = ((aWandererK + RotL64(aPrevious, 5U)) + 0xA516BAABC34D1128ULL) + aKeyRotateBOrbiterAssignSaltF[(((255U - aIndex) + 237U)) & S_SALT1];
